// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITetherToken {
    function transfer(address _to, uint _value) external;
    function transferFrom(address _from, address _to, uint _value) external;
    function approve(address _spender, uint _value) external;
    function balanceOf(address who) external view returns (uint);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);
    ITetherToken target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ITetherToken(TARGET);
        vm.label(TARGET, "TetherToken");
        vm.label(attacker, "Attacker");
        // Inject tokens to attacker
         deal(TARGET, attacker, 1000 * 1e6); // USDT has 6 decimals
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get initial balance
        uint256 initialBalance = target.balanceOf(attacker);

        // Prepare transfer call data: transfer(address,uint256)
        bytes memory callData = abi.encodeWithSignature("transfer(address,uint256)", address(0xdead), 100 * 1e6);

        // Make low-level call to capture return data
        (bool success, bytes memory returnData) = TARGET.call(callData);

        // ERC20 standard requires 32 bytes return data (bool true = 0x...01)
        // Non-conformant tokens return 0 bytes
        uint256 returnDataLength = returnData.length;

        // Demonstrate the vulnerability: return data should be 32 bytes but is 0
        assertEq(returnDataLength, 0, "Transfer should return 0 bytes (non-conformant)");
        assertEq(success, true, "Call should succeed");

        // Verify balance changed (transfer worked despite non-conformity)
        uint256 finalBalance = target.balanceOf(attacker);
        assertLt(finalBalance, initialBalance, "Balance should decrease after transfer");

        // This proves: transfer() works but doesn't return bool as ERC20 requires
        // Contracts expecting bool return would fail when integrating with this token
        // assertTrue(transfer() return value != true (boolean return expected by ERC20 standard), "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

